		public void TestMenuHaveCaptureFromCustomsOption()
		{
			using (var menu = new EDIMenu())
			{
				var declaration = Factory.New<JobDeclaration>();
				menu.Declaration = declaration;

				declaration.JE_ApplicationCode = DeclarationApplicationCodeList.Codes.Builtin;
				menu.RefreshMenu();
				var captureMenuItem = menu.MenuItems.FindByText("Capture from Customs");
				AssertNotNull(captureMenuItem);
				AssertEquals(true, captureMenuItem.Visible);

				declaration.JE_ApplicationCode = DeclarationApplicationCodeList.Codes.Interfaced;
				menu.RefreshMenu();
				captureMenuItem = menu.MenuItems.FindByText("Capture from Customs");
				AssertNotNull(captureMenuItem);
				AssertEquals(false, captureMenuItem.Visible);
			}
		}

