						AssertEquals("Entry has 1 outgoing message of type T2Q for Export", 1, entryHeader.Messages.Cast<EDIMessage>().Count(x => x.EM_ReceiveTransmit == "TRX" && x.EM_MessageType == "T2Q"));

						declaration.JE_MessageType = Common.Shared.SharedJobMessageTypeList.Codes.Import;
