						declaration.JE_MessageType = Common.Shared.SharedJobMessageTypeList.Codes.Import;
						declaration.CustomsEntryInstructions[0].CEI_SubStyle = EntrySubStyleList.Codes.T2C;
						declaration.Factory.Save();
						menu.RefreshMenu();
						captureFromCustomsMenuItem.PerformClick();
