						var entryHeader = declaration.CustomsEntryHeaders[0];
						entryHeader.ZG_POUSVersion = 1;
						declaration.Factory.Save();
						menu.RefreshMenu();
						captureFromCustomsMenuItem.PerformClick();
						AssertContains("Data Capture Request can not be sent when there is no MRN so nothing will be sent and no message will be shown", ZString.Empty, UnitTestUserNotification.Instance.LastMessage.Text);

						entryHeader.MovementReferenceNumberSetter("20ES00999830001277", ZDateTime.Today);
						entryHeader.SetCSVClearanceNum("Test");
						declaration.Factory.Save();
						menu.RefreshMenu();
						captureFromCustomsMenuItem.PerformClick();
						AssertContains("Data Capture Request can not be sent when CSV Clearance is not empty so nothing will be sent and no message will be shown", ZString.Empty, UnitTestUserNotification.Instance.LastMessage.Text);

						entryHeader.SetCSVClearanceNum(ZString.Empty);
						declaration.Factory.Save();
						menu.RefreshMenu();
						TestHelper.CheckFactoryHasNoPendingChanges("Before capture", declaration.Factory);
						captureFromCustomsMenuItem.PerformClick();
						TestHelper.CheckFactoryHasNoPendingChanges("After capture", declaration.Factory);
						AssertEquals("Message sent correctly for T2C", true, UnitTestUserNotification.Instance.PreviousMessages.ContainsMessageContainingThisText("1 Message sent successfully."));
						AssertEquals("Entry has 1 outgoing message of type T2Q for T2C", 1, entryHeader.Messages.Cast<EDIMessage>().Count(x => x.EM_ReceiveTransmit == "TRX" && x.EM_MessageType == "T2Q"));
					}
				});
			}
		}

