		public void TestCaptureFromCustoms_SendDocumentRequestImport_AllDocumentsNeeded_InstructionA_AEAT()
		{
			using (var menu = new SendMenuForTest())
			{
				var declaration = Factory.NewWithValidTestData<JobDeclaration>();
				declaration.JE_MessageType = Common.Shared.SharedJobMessageTypeList.Codes.Import;
				declaration.JE_ApplicationCode = "BLT";
				declaration.JE_MergeBy = OrgConstants.MergeInvoiceLines.Tariff;
				declaration.ZG_IsTrainingDeclaration = true;

				var invoiceHeader = declaration.Invoices.AddNew();
				invoiceHeader.InvoiceLines.AddNew();
				declaration.Factory.Save();

				ZFormModaliser.ShowDialogsInTest = false;
				ZFormModaliser.ResultToReturnFromShowDialog = DialogResult.OK;
				var captureFromCustomsMenuItem = menu.MenuItems.FindByText("Capture from Customs");

				menu.Declaration = declaration;
				CombineAssertions(() =>
				{
					menu.RefreshMenu();
					captureFromCustomsMenuItem.PerformClick();
					AssertEquals("Message informing broker and certificate are needed", "Cannot send message without a broker and valid certificate; please enter the broker and a valid certificate under the miscellaneous options.", UnitTestUserNotification.Instance.LastMessage.Text);

					declaration.JE_GS_NKCusAgent = Staff.GS_Code;
					declaration.JE_CustomsProfile = ZString.Empty;
					declaration.Factory.Save();
					menu.RefreshMenu();
					captureFromCustomsMenuItem.PerformClick();
					AssertEquals("Message informing broker and certificate are needed when broker is declared but certificate is empty", "Cannot send message without a broker and valid certificate; please enter the broker and a valid certificate under the miscellaneous options.", UnitTestUserNotification.Instance.LastMessage.Text);

					declaration.JE_CustomsProfile = "INVALID";
					declaration.Factory.Save();
					menu.RefreshMenu();
					captureFromCustomsMenuItem.PerformClick();
					AssertEquals("Message informing broker and certificate are needed when broker is declared but certificate declared is invalid", "Cannot send message without a broker and valid certificate; please enter the broker and a valid certificate under the miscellaneous options.", UnitTestUserNotification.Instance.LastMessage.Text);

					declaration.JE_CustomsProfile = BuilderHelperTest.CertificateName;
					declaration.Factory.Save();
					menu.RefreshMenu();
					captureFromCustomsMenuItem.PerformClick();
					AssertEquals("Message informing broker and certificate are needed when broker is declared but current user has no authorisation for certificate declared", "Cannot send message without a broker and valid certificate; please enter the broker and a valid certificate under the miscellaneous options.", UnitTestUserNotification.Instance.LastMessage.Text);

					UnitTestUserNotification.Instance.ClearMessagesAndAnswers();
					AssertNull("User Notification Last Message was cleared", UnitTestUserNotification.Instance.LastMessage.Text);
					declaration.Reload();
					menu.RefreshMenu();
					captureFromCustomsMenuItem.PerformClick();
					AssertEquals("Message informing broker and certificate are needed when broker is declared but current user has no authorisation for certificate declared, even if we haven't done a new save& validation", "Cannot send message without a broker and valid certificate; please enter the broker and a valid certificate under the miscellaneous options.", UnitTestUserNotification.Instance.LastMessage.Text);

					using (Env.SetTemporaryUserContext(new UserContext(Staff, Env.CurrentBranchPK, Env.CurrentDepartmentPK)))
					{
						declaration = Factory.GetNewJobDeclaration(Staff, Supplier, Importer, Declarant, messageType: Common.Shared.SharedJobMessageTypeList.Codes.Import);
						declaration.Factory.Save();

						menu.Declaration = declaration;
						menu.RefreshMenu();
						captureFromCustomsMenuItem.PerformClick();
						AssertContains("Document Capture Requests can not be sent when there is no MRN so nothing will be sent and no message will be shown", ZString.Empty, UnitTestUserNotification.Instance.LastMessage.Text);

						var entryHeader = declaration.CustomsEntryHeaders[0];
						entryHeader.MovementReferenceNumberSetter("20ES00999830001277", ZDateTime.Today);
						entryHeader.SetCSVClearanceNum("ABCDEFGHIJKLMNOP");
						entryHeader.ZG_CSVImportCertificate = "ZYXWVUTSRQPONMLK";
						declaration.Factory.Save();
						menu.RefreshMenu();
						TestHelper.CheckFactoryHasNoPendingChanges("Before capture", declaration.Factory);
						captureFromCustomsMenuItem.PerformClick();
						TestHelper.CheckFactoryHasNoPendingChanges("After capture", declaration.Factory);
						AssertContains("4 Document Capture request(s) created", UnitTestUserNotification.Instance.LastMessage.Text);
					}
				});
			}
		}

