						var entryHeader = declaration.CustomsEntryHeaders[0];
						entryHeader.MovementReferenceNumberSetter("20ES00999830001277", ZDateTime.Today);
						declaration.Factory.Save();
						menu.RefreshMenu();
						captureFromCustomsMenuItem.PerformClick();
						AssertContains("EXS Document Capture Request can not be sent when CSV Clearance is empty so nothing will be sent and no message will be shown", ZString.Empty, UnitTestUserNotification.Instance.LastMessage.Text);

