		class SendFormForTest : MessageSendingForm
		{
			public SendFormForTest(Business.MessageSending.JobDeclarationMessageSendingObjectParent declarationWrapper, string messageType, string messageSubType)
				: base(declarationWrapper)
			{
				foreach (JobDeclarationMessageSendingObject sendingObject in declarationWrapper.SendingObjectsCollection)
				{
					sendingObject.ShouldSend = true;
					sendingObject.MessageSubType = messageSubType;
					sendingObject.MessageType = messageType;
				}
			}

			public ZGrid MessageSendingGrid => base.MessageSendingObjectsGrid;
		}

		class SendMenuForTest : EDIMenu
		{
			public SendMenuForTest(string messageType = DeclarationMessageTypeList.Codes.ExportUcc6, string messageSubType = DeclarationMessageSubTypeList.Codes.OriginalDeclaration) : base()
			{
				this.messageType = messageType;
				this.messageSubType = messageSubType;
			}
			readonly ZString messageType;
			readonly ZString messageSubType;

			public new MenuItem sendToCustomsMenuItem => base.sendToCustomsMenuItem;
			protected override MessageSendingForm GetMessageSendingForm(Business.MessageSending.JobDeclarationMessageSendingObjectParent decWrapper)
				=> new SendFormForTest(decWrapper, messageType, messageSubType);
			protected override MessageEditForm GetMessageEditForm()
				 => new MessageEditFormForTest();
		}

		class MessageEditFormForTest : MessageEditForm
		{
			public MessageEditFormForTest()
				: base()
			{
			}

			public override (ZString, ZBool) EditMessage(ZString messageText) => (messageText.Replace("Description1", "AAAAAAAAAAAAA"), true);
		}

